fun main() {
    val a = 4000000000u
    val b = 5u
    println(a)
    println(b)
    println(a + b)
    println(a - b)
    println(b - a)
    println(a * b)
    println(a / b)
    println(a % 7u)
    println(a > b)
    println(a.compareTo(b))
    println(a.toInt())
    println(a.toLong())
    println(a.toDouble())
    println((-1).toUInt())
    println(UInt.MAX_VALUE)
    println(UInt.MIN_VALUE)
    println(ULong.MAX_VALUE)
    println(ULong.MAX_VALUE / 10uL)
    println(ULong.MAX_VALUE % 10uL)
    println(ULong.MAX_VALUE.toDouble())
    println(18446744073709551615uL)
    println(12345678901234uL * 1000uL)
    println(a shr 4)
    println(a shl 1)
    println(a and 0xFFu)
    println(a or 1u)
    println(a xor a)
    println(b.inv())
    val x: UByte = 200u
    val y: UByte = 100u
    println(x + y)
    println((x + y).toUByte())
    println(x.toInt())
    println(x * y)
    println(x > y)
    println(UByte.MAX_VALUE)
    val s: UShort = 65535u
    println(s)
    println(s + 1u)
    println(s.toShort())
    println((-1).toByte().toUByte())
    println((-1).toByte().toUInt())
    println(300.toUByte())
    println(3000000000L.toULong())
    println(3000000000L.toUInt())
    val an: UInt? = a
    println(an)
    val nn: UInt? = null
    println(nn)
    println(an == a)
    val any: Any = b
    println(any is UInt)
    println(any is Int)
    println(any)
    val l = listOf(3u, 1u, 2u)
    println(l)
    println(l.sorted())
    println(l.maxOrNull())
    val arr = UIntArray(3)
    arr[0] = 4000000000u
    arr[1] = 1u
    arr[2] = arr[0] + arr[1]
    println(arr.size)
    println(arr.contentToString())
    val ua = uintArrayOf(1u, 2u, 3u)
    var sum = 0u
    for (e in ua) sum += e
    println(sum)
    for (i in 0u..3u) print("$i ")
    println()
    for (i in 10u downTo 7u) print("$i ")
    println()
    for (i in 0u until 10u step 3) print("$i ")
    println()
    println(5u in 1u..9u)
    println(a.hashCode())
    println(5uL.hashCode())
    println(b == 5u)
    println("123".toUInt())
    println("18446744073709551615".toULong())
    println("x".toUIntOrNull())
    println(1e10.toULong())
    println(3.9.toUInt())
    println((-3.9).toUInt())
    println(maxOf(3u, 9u))
    val bytes = ubyteArrayOf(1u, 255u)
    println(bytes.contentToString())
    println(7u.mod(3u))
    println(7u.floorDiv(2u))
    var c = 0u
    c++
    c += 5u
    println(c)
    println(0u - 1u)
    println(0uL - 1uL)
    println(1uL shl 63)
    println((1uL shl 63) / 3uL)
    println((1uL shl 63) % 1000uL)
    println((1uL shl 63) > 5uL)
    println(0xFFFFFFFFuL.toUInt())
    println(0x80000000u)
}
